static void virtnet_del_vqs(struct virtnet_info *vi) /* <=== virtnet_del_vqs */ 
{
	struct virtio_device *vdev = vi->vdev;

	virtnet_clean_affinity(vi, -1);

	vdev->config->del_vqs(vdev);

	virtnet_free_queues(vi);
}

static inline struct virtio_net_hdr_mrg_rxbuf *skb_vnet_hdr(struct sk_buff *skb) /* <=== skb_vnet_hdr */ 
{
	return (struct virtio_net_hdr_mrg_rxbuf *)skb->cb;
}

void napi_hash_del(struct napi_struct *napi) /* <=== napi_hash_del */ 
{
	spin_lock(&napi_hash_lock);

	if (test_and_clear_bit(NAPI_STATE_HASHED, &napi->state))
		hlist_del_rcu(&napi->napi_hash_node);

	spin_unlock(&napi_hash_lock);
}

