				      const struct cpumask *mask,
				      u16 index)
{
	return 0;
}

static inline u16 virtio16_to_cpu(struct virtio_device *vdev, __virtio16 val) /* <=== virtio16_to_cpu */ 
{
	return __virtio16_to_cpu(virtio_is_little_endian(vdev), val);
}

static void virtnet_set_affinity(struct virtnet_info *vi) /* <=== virtnet_set_affinity */ 
{
	int i;
	int cpu;

	/* In multiqueue mode, when the number of cpu is equal to the number of
	 * queue pairs, we let the queue pairs to be private to one cpu by
	 * setting the affinity hint to eliminate the contention.
	 */
	if (vi->curr_queue_pairs == 1 ||
	    vi->max_queue_pairs != num_online_cpus()) {
		virtnet_clean_affinity(vi, -1);
		return;
	}

	i = 0;
	for_each_online_cpu(cpu) {
		virtqueue_set_affinity(vi->rq[i].vq, cpu);
		virtqueue_set_affinity(vi->sq[i].vq, cpu);
		netif_set_xps_queue(vi->dev, cpumask_of(cpu), i);
		i++;
	}

	vi->affinity_hint_set = true;
}

static int rxq2vq(int rxq) /* <=== rxq2vq */ 
{
	return rxq * 2;
}

static inline __virtio16 cpu_to_virtio16(struct virtio_device *vdev, u16 val) /* <=== cpu_to_virtio16 */ 
{
	return __cpu_to_virtio16(virtio_is_little_endian(vdev), val);
}

void free_netdev(struct net_device *dev) /* <=== free_netdev */ 
{
	struct napi_struct *p, *n;

	netif_free_tx_queues(dev);
#ifdef CONFIG_SYSFS
	kvfree(dev->_rx);
#endif

	kfree(rcu_dereference_protected(dev->ingress_queue, 1));

	/* Flush device addresses */
	dev_addr_flush(dev);

	list_for_each_entry_safe(p, n, &dev->napi_list, dev_list)
		netif_napi_del(p);

	free_percpu(dev->pcpu_refcnt);
	dev->pcpu_refcnt = NULL;

	/*  Compatibility with error handling in drivers */
	if (dev->reg_state == NETREG_UNINITIALIZED) {
		netdev_freemem(dev);
		return;
	}

	BUG_ON(dev->reg_state != NETREG_UNREGISTERED);
	dev->reg_state = NETREG_RELEASED;

	/* will free via device release */
	put_device(&dev->dev);
}

static inline void sg_set_buf(struct scatterlist *sg, const void *buf, /* <=== sg_set_buf */ 
			      unsigned int buflen)
{
#ifdef CONFIG_DEBUG_SG
	BUG_ON(!virt_addr_valid(buf));
